        "contextRight": "「这是你能看见的。」伊莱莎说，「双关利用词语的多义性——同一个词，同时说了两件事。在莎士比亚里这无处不在，有时是笑料，有时是刀子。grave 那个例子：一个垂死的人说自己会成为「a grave man」——既是'严肃的人'，也是'躺在坟墓里的人'。笑声和悲剧同时发生在一句话里。」",
