        "context": "「双关，英文 pun，是莎士比亚最喜欢的语言游戏。」伊莱莎在黑板上写下这个词，「双关的定义是：利用同一个词语的多重含义，或者两个发音相似的词，同时表达两层意思。」她停了一下，「举个例子——英文单词 grave，既是形容词'严肃的'，也是名词'坟墓'。在《罗密欧与朱丽叶》里，一个被刺伤的人说他明天会成为'a grave man'——严肃的人，也是死在墓里的人。一句话里，笑声和死亡同时存在。」她转过来，「你们在对角巷里是不是也遇到过这种语言把戏？很多巫师的名字和地名都藏着双关——那是文字的暗门。莎士比亚最擅长在门后放刀。」"
