        "context": "「意象，英文 imagery，是文学里最核心的工具之一。」伊莱莎走到窗边，「意象的定义是：用具体的感官细节来表达抽象的情感或思想。爱情是抽象的，你没办法直接看见它、摸到它——但你可以写'爱情是玫瑰'，那朵玫瑰你能想象它的颜色、它的香气、它刺入皮肤的感觉。意象把抽象的东西变成了你能用感官体验的东西。莎士比亚在《仲夏夜之梦》里用了大量自然意象：月亮、花朵、树影——这些具体的画面烘托出了梦境般的、游离于现实边缘的情感。当你在阅读一首诗或一段戏剧时，注意那些具体的、可感知的细节——那些就是意象，它们是作家用来传递情感的工具。」",
