        "contextRight": "「这是你能看见的。」伊莱莎轻声说，「顿悟时刻——一个人物突然理解了某件事，或者读者突然看清了什么。这是短篇小说区别于小说的核心。爱尔兰作家乔伊斯把这个概念称为 epiphany——如神启示般的顿悟。短篇小说的所有叙述都指向那一刻。」",
        "contextWrong": "「你读到了什么？」伊莱莎轻声问，「短篇小说的限制不在题材，也不在语言难度——而在结构。它没有时间做铺垫，必须把所有力量集中在最关键的那个瞬间上。」",
        "context": "「短篇小说，英文 short story，通常在一千到一万五千字之间。」伊莱莎把薄书放回桌上，「它和小说的差别不只是长短——是一种根本不同的叙事策略。短篇小说不建造世界，它捕捉一个瞬间。它的焦点是单一的：一个场景，一个事件，一两个人物。」她在黑板上写下 epiphany 这个词，「短篇小说常常以一个'顿悟时刻'为核心——英文叫 epiphany，来自希腊文，原意是'显现'。那是某人突然看清楚了某件事的那一刻。整篇故事的所有叙述，都是在为那一刻积蓄力量。」她停了一下，「你们知道魔药里有一种叫做'瞬间洞察液'的东西吗？短篇小说的结构就有点类似——它把所有的叙述浓缩成一滴，那一滴让你瞬间看清楚了什么。」",
