        "question": {
          "leadIn": "伊莱莎在黑板左边的「我」下面加了几个字：「只知道自己的内心」。「想象一下，」她轻声说，「你在一个密室里——你只能看见自己能看见的，听见自己能听见的。别人的脑袋里在想什么，你不知道。」",
          "text": "「以下哪一项是第一人称叙述的核心特征？」",
          "options": [
            "叙述者知道所有人物的内心活动",
            "叙述者只能描述自己经历和感受到的",
            "叙述者从不参与故事，只是旁观",
            "叙述者必须说实话"
          ],
          "answer": 1
        },
        "contextRight": "「这是你能看见的。」伊莱莎说，「第一人称叙述者只能告诉我们他自己经历和感受到的东西。其他人物的内心，他猜测，但不确定。这种限制制造了一种很强的亲密感——你和叙述者站在同一个地方，一起摸索；但也制造了危险：如果叙述者有偏见或者在撒谎，读者很难发现。」",
        "contextWrong": "「你再听一遍。」伊莱莎平静地说，「第一人称叙述——'我'。'我'只知道自己的感受，只能描述自己看见的和经历的。其他人物在想什么，'我'无法直接进入，只能推测。」",
        "context": "「叙述者视角，英文叫 point of view 或 narrative perspective，是文学分析里最基本的问题之一。」伊莱莎在黑板上指着「我」，「第一人称叙述的定义是：叙述者使用'我'（英文 I）来讲故事，并且是故事中的一个人物。这意味着叙述者只知道自己的想法和感受——他看见什么，读者才能看见什么；他不知道的事，读者也不知道。」她停了一下，「这种局限性制造了两种效果：一是亲密感——读者和叙述者一起经历，就像收到了一封私信；二是不确定性——我们只能相信叙述者告诉我们的，而叙述者可能有偏见，可能撒谎，可能根本没有注意到最重要的事情。在文学里，我们叫这种叙述者'不可靠叙述者'——他的话需要被质疑。」"
