        "context": "「第三人称全知叙述，英文叫 third-person omniscient，是另一种截然不同的策略。」伊莱莎在黑板右边的「他/她/它」下面写上「全知」，「全知的意思是：这个叙述者不是故事里的人物，而是一个站在故事之外的声音，可以同时进入任何人物的内心，可以跳到任何地点和时间。」她停了一下，「这是一种'上帝视角'——叙述者知道每个人在想什么，包括读者不知道的秘密，包括还没发生的事情的暗示。狄更斯和简·奥斯汀都大量使用这种视角。它让作者可以同时铺设多条故事线，可以建立讽刺效果——因为读者知道某个人物不知道的事，于是产生了一种优越感或者悬念。」她转身，「但全知叙述也有代价：叙述者和故事的距离更远，那种只有第一人称才能给出的亲密和脆弱，全知叙述很难做到。」",
