        "context": "「哥特文学，英文 Gothic literature，是18世纪末在英国兴起的一种文学类型。」伊莱莎走到黑板前，「哥特这个词本来指中世纪的建筑风格——高耸的尖顶、阴暗的长廊、地下室。哥特文学借用了这种建筑氛围：黑暗、秘密、古老、令人不安。哥特文学的定义是：一种以阴暗神秘的场景、超自然或怪异事件、强烈的恐惧情绪为核心的文学类型，通常探索理性无法解释的领域——死亡的边界、疯狂的心智、禁忌的创造。」她停了一下，「哥特文学不只是为了恐怖——它是一种严肃的文学形式，用来探索那些被正统社会压抑的东西：性别与权力、科学的道德边界、被抛弃的生命。」"
