        "context": "「哥特文学有一套固定的场景工具。」伊莱莎在黑板上指着清单，「古老的城堡、荒废的庄园、修道院的废墟——这些建筑的共同点是：它们都有秘密，有被遗忘的历史，有可以把人关在里面的空间。荒原、悬崖、暴风雨——这些自然景观的共同点是：它们不受人类控制，充满危险，让人渺小。」她停了一下，「哥特场景的功能不只是视觉氛围——它是人物内心状态的外化。当《呼啸山庄》的人物在约克郡荒原上奔跑，那片荒原不只是地点，它是主角内心的野性和不安的物质化。文学里，内心和外部世界往往是互相呼应的。」",
